import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import axios from "axios";

export default function ListarTodos() {
  const [usuarios, setUsuarios] = useState([]);

  useEffect(() => {
    axios.get("http://localhost:3001/usuarios")
      .then(res => setUsuarios(res.data))
      .catch(err => console.error("Erro ao buscar usuários:", err));
  }, []);

  return (
    <div>
      <h3>Todos os Usuários</h3>
      <table className="table table-striped">
        <thead className="table-dark">
          <tr>
            <th>Nome</th>
            <th>Idade</th>
            <th>Bairro</th>
            <th>Estado</th>
            <th>Foto</th>
            <th>Ações</th>
          </tr>
        </thead>
        <tbody>
          {usuarios.map(usuario => (
            <tr key={usuario.id}>
              <td>{usuario.nome}</td>
              <td>{usuario.idade}</td>
              <td>{usuario.bairro}</td>
              <td>{usuario.estado}</td>
              <td>
                {usuario.imagem && (
                  <img
                    src={`http://localhost:3001${usuario.imagem}`}
                    alt="Foto"
                    style={{
                      width: "50px",
                      height: "50px",
                      objectFit: "cover",
                      borderRadius: "50%"
                    }}
                  />
                )}
              </td>
              <td>
                <Link to={`/usuarios/${usuario.id}`} className="btn btn-sm btn-info me-2">
                  Ver
                </Link>
                <Link to={`/editar/${usuario.id}`} className="btn btn-sm btn-warning">
                  Editar
                </Link>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
